TAX = {
  "format": {"ugc": "Phone-shot testimonial", "studio": "Studio product shot",
             "static": "Still image with text overlay", "carousel": "Multi-image carousel"},
  "cta":    {"trial": "Free trial", "demo": "Book a demo", "shop": "Shop now",
             "learn": "Learn more", "none": "No call to action"},
  "funnel": {"top": "Problem aware", "mid": "Comparing options",
             "bottom": "Ready to buy"}}

def tag(ad_copy):
    qs = {k: {"type": "choice", "criteria": v,
              "instructions": "Which %s is this ad?" % k} for k, v in TAX.items()}
    return decide(ad_copy, qs)   # one call, three typed tags

RUBRIC = ["Fluff", "Context", "Useful", "Quotable", "Clip gold"]

def score(chunk):
    qs = {"clip": {"type": "score", "criteria": RUBRIC,
          "instructions": "Consider only this passage. How strong is it as a standalone short clip?"}}
    return decide(chunk["text"], qs)["clip"]["score"]

top = sorted(chunks, key=score, reverse=True)[:10]
for c in top:
    print(c["start"], c["end"], c["text"][:60])

def link_for(paragraph, pages):
    targets = {p["slug"]: p["title"] for p in pages}
    targets["none"] = "No useful target in this list"
    qs = {
      "target": {"type": "choice", "criteria": targets,
        "instructions": "Which existing page should this paragraph link to?"},
      "worth": {"type": "noul",
        "instructions": "Would that link genuinely help a reader of this paragraph?"}}
    ans = decide(paragraph, qs)
    if ans["worth"]["noul"] < 0.7 or ans["target"]["choice"] == "none":
        return None
    return ans["target"]["choice"]

KINDS = {"buy": "Wants to buy, needs a link or price",
         "ask": "Question about the product or shipping",
         "moan": "Complaint or bad experience",
         "chat": "Comment with no commercial content"}

def tag(comment):
    state = "Post about: %s. Comment: %s" % (comment["post"], comment["text"])
    qs = {"kind": {"type": "choice", "criteria": KINDS,
                    "instructions": "How should this comment be handled?"}}
    ans = decide(state, qs)["kind"]
    return ans if ans["confidence"] > 0.55 else {"choice": "chat"}

MODELS = {
  "cheap": "Short lookup, formatting or extraction",
  "mid": "Normal edit, explanation or small refactor",
  "frontier": "Multi-step reasoning, architecture, hard bugs"}

def route(message):
    qs = {"model": {"type": "choice", "criteria": MODELS,
          "instructions": "Which model tier does this request need?"}}
    ans = decide(message, qs)["model"]
    # the cutoff lives here, not in the prompt
    return "frontier" if ans["probabilities"].get("frontier", 0) > 0.45 else ans["choice"]

async function judge(text) {
  const r = await fetch('https://api.venice.ai/api/v1/decisions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json',
               Authorization: 'Bearer ' + KEY },
    body: JSON.stringify({
      model: 'jev-latest',
      state: text.slice(0, 600),
      questions: { slop: { type: 'noul',
        instructions: 'Is this post low-effort machine-generated filler?' } }
    })
  });
  return (await r.json()).answers.slop.noul;
}

for (const el of document.querySelectorAll('.feed-item')) {
  if (await judge(el.innerText) > 0.7) el.style.display = 'none';
}

async function findOnPage(query, sections) {
  const criteria = Object.fromEntries(sections.map((s, i) =>
    ['s' + i, s.heading + ': ' + s.text.slice(0, 120)]));
  criteria.none = 'No section matches';

  const ans = await decide({
    model: 'jev-latest',
    state: 'Query: ' + query,
    questions: { hit: { type: 'choice', criteria,
      instructions: 'Which section of this page answers the query?' } }
  });

  if (ans.hit.choice !== 'none') {
    sections[Number(ans.hit.choice.slice(1))]
      .el.scrollIntoView({ behavior: 'smooth' });
  }
}

def find(query, assets):
    criteria = {a["id"]: a["caption"][:140] for a in assets}
    criteria["none"] = "Nothing in the library matches"
    qs = {"hit": {"type": "choice", "criteria": criteria,
      "instructions": "Which asset is the query asking for?"}}
    ans = decide("Query: " + query, qs)["hit"]
    return None if ans["choice"] == "none" else ans["choice"]

